// Account defines model for Account.
type Account struct {
	// Bio [optional] Profile biography or description
	Bio *string `json:"bio,omitempty"`

	// BrandId [always] SocialAPI brand ID this account belongs to
	BrandId string `json:"brand_id"`

	// ConnectionType [optional] LinkedIn only: "profile" for a member profile, "organization" for a company Page. Absent for every other account
	//
	// Example: profile
	ConnectionType *ConnectionType `json:"connection_type,omitempty"`

	// EffectivePermissions [always] The permissions this account can use right now: the requested permissions the platform supports, minus any the platform did not grant or has since refused. Uses the same names as permissions. An empty list when none apply
	EffectivePermissions *[]string `json:"effective_permissions"`

	// Id [always]
	//
	// Example: acc_01HZ9X3Q4R5M6N7P8V2K0W1J
	Id string `json:"id"`

	// LoginId [optional] Login id shared by accounts connected in the same authorization (facebook, google, linkedin)
	LoginId *string `json:"login_id,omitempty"`

	// Metadata [optional] Platform-specific keys for this account
	Metadata *map[string]interface{} `json:"metadata,omitempty"`

	// Name [always] Display name of the account or page
	//
	// Example: Acme Corp
	Name string `json:"name"`

	// PageName [optional] Name of the single active page bound to this account; set only when exactly one page is active (e.g. facebook), so clients can label the tile with the page instead of the login identity
	PageName *string `json:"page_name,omitempty"`

	// Permissions [always] The permissions requested for this account: one or more of posts.read, posts.write, comments.read, comments.write, messages.read, messages.write, reviews.read, reviews.write, analytics.read. null means every permission, including ones added later
	Permissions *[]string `json:"permissions"`

	// Platform [always]
	//
	// Example: instagram
	Platform Platform `json:"platform"`

	// ProfilePictureUrl [optional] Profile picture URL
	ProfilePictureUrl *string `json:"profile_picture_url,omitempty"`

	// ReconnectReason [optional] Human-readable reason; only set when Status == "reconnect_required"
	ReconnectReason *string `json:"reconnect_reason,omitempty"`

	// Status [always] One of: active, reconnect_required
	//
	// Example: active
	Status string `json:"status"`

	// Username [always] May equal Name on platforms without a distinct handle
	//
	// Example: acmecorp
	Username string `json:"username"`
}

